/* @lc app=leetcode id=2301 lang=kotlin */
class Solution { fun matchReplacement(s: String, sub: String, mappings: Array<CharArray>): Boolean = BooleanArray(128 * 128).apply { mappings.forEach { this[it[0].code * 128 + it[1].code] = true }.also { (0..127).forEach { i -> this[i * 128 + i] = true } } }.let { m -> (0..s.length - sub.length).any { i -> sub.indices.all { j -> m[sub[j].code * 128 + s[i + j].code] } } } }